'use strict';
let auditCategoryFilter='all',auditQuery='',auditFrom='',auditTo='',auditPage=1;
const auditCategories={all:'全部',cases:'案件',warehouse:'庫房',plating:'電鍍',wire:'線材',system:'系統與權限',unknown:'未分類'};
function auditCategory(entry){if(Object.hasOwn(auditCategories,entry.category)&&entry.category!=='all')return entry.category;const loc=entry.location||'',id=entry.project||'';if(id.startsWith('wire:'))return'wire';if(id.startsWith('plating:'))return'plating';if(loc.startsWith('庫房管理')||[...(state.projects||[]),...(state.deletedProjects||[]).map(x=>x.project)].some(p=>p.id===id))return'warehouse';if(loc.startsWith('電鍍管理'))return'plating';if(loc.startsWith('線材管理'))return'wire';if(loc.startsWith('案件管理')||loc.startsWith('管理後台 > 案件'))return'cases';if(loc.startsWith('管理後台 > 庫房'))return'warehouse';if(loc.startsWith('管理後台 > 電鍍'))return'plating';if(loc.startsWith('管理後台 > 線材'))return'wire';if(/^(管理後台|網站管理|資訊庫)/.test(loc))return'system';return'unknown';}
function auditTarget(entry){if(entry.target)return entry.target;const location=entry.location||'';if(location.startsWith('管理後台 > ')&&['刪除','還原'].includes(entry.action))return entry.detail||location;if(location.includes(' > '))return location.split(' > ').slice(1).join(' > ');const id=entry.project||'';if(id.startsWith('wire:'))return (state.wireTypes||[]).find(t=>t.id===id.slice(5))?.name||'原線材（未記錄名稱）';if(id.startsWith('plating:'))return (state.platingProjects||[]).find(p=>p.id===id.slice(8))?.name||'原電鍍案件（未記錄名稱）';const p=[...(state.projects||[]),...(state.deletedProjects||[]).map(x=>x.project)].find(p=>p.id===id);return p?.name||entry.detail||location||'未記錄對象';}
const addAuditBeforeView=addAudit;addAudit=function(action,detail,location,projectId=''){addAuditBeforeView(action,detail,location,projectId);const entry=state.logs[0];entry.category=auditCategory(entry);entry.target=auditTarget(entry);};
function filteredAudit(){return (state.logs||[]).filter(x=>{const date=new Date(x.time);const day=Number.isNaN(date.getTime())?'':date.toLocaleDateString('sv-SE');return(auditCategoryFilter==='all'||auditCategory(x)===auditCategoryFilter)&&(!auditFrom||day>=auditFrom)&&(!auditTo||day<=auditTo)&&[x.actor,x.action,x.detail,x.location,auditTarget(x)].join(' ').toLowerCase().includes(auditQuery.trim().toLowerCase());}).sort((a,b)=>String(b.time).localeCompare(String(a.time)));}
auditRows=function(){return '';};
function enhanceAuditView(){const body=$('.audit-body');if(!body||!auditUnlocked||currentUser.role!=='supervisor')return;
 body.innerHTML='<div class="audit-tabs">'+Object.entries(auditCategories).map(([key,label])=>'<button type="button" data-audit-category="'+key+'" class="'+(key===auditCategoryFilter?'primary':'')+'">'+label+'</button>').join('')+'</div><div class="audit-search"><input id="audit-query" placeholder="搜尋案名、線材、人員或內容" value="'+esc(auditQuery)+'"><label>開始日期<input type="date" id="audit-from" value="'+auditFrom+'"></label><label>結束日期<input type="date" id="audit-to" value="'+auditTo+'"></label><button type="button" id="audit-export-filtered">匯出目前篩選</button><button type="button" id="audit-export-all">匯出全部紀錄</button><button type="button" id="audit-lock-new">鎖定資訊庫</button><details><summary>更多操作</summary><button type="button" class="danger-button" id="audit-clear-new">刪除全部紀錄</button></details></div><div id="audit-results"></div>';
 function draw(){const logs=filteredAudit(),pages=Math.max(1,Math.ceil(logs.length/20));auditPage=Math.min(auditPage,pages);
 $('#audit-results').innerHTML='<p class="muted">符合 '+logs.length+' 筆 · 第 '+auditPage+'／'+pages+' 頁</p><div class="audit-compact-table"><div class="audit-compact-head"><span>時間</span><span>人員</span><span>對象</span><span>操作</span><span>內容</span><span>刪除</span></div>'+logs.slice((auditPage-1)*20,auditPage*20).map(x=>'<div class="audit-compact-row" data-history-log="'+esc(x.id)+'"><time>'+esc(receiptTime(x.time))+'</time><span>'+esc(x.actor||'未記錄人員')+'</span><strong title="'+esc(auditTarget(x))+'">'+esc(auditTarget(x))+'</strong><span>'+esc(x.action||'操作紀錄')+'</span><span class="audit-content" title="'+esc(x.detail||'')+'">'+esc(x.detail||'')+'</span>'+textLogDeleteButton(x.id)+'</div>').join('')+'</div>'+(!logs.length?'<p class="empty">沒有符合條件的紀錄</p>':'')+'<div class="audit-pager"><button type="button" id="audit-prev" '+(auditPage===1?'disabled':'')+'>上一頁</button><button type="button" id="audit-next" '+(auditPage===pages?'disabled':'')+'>下一頁</button></div>';
 $('#audit-results').querySelectorAll('[data-text-log-delete]').forEach(button=>button.onclick=async e=>{e.preventDefault();e.stopPropagation();button.disabled=true;try{if(await deleteTextLog(button.dataset.textLogDelete))draw();}finally{if(button.isConnected)button.disabled=false;}});
 $('#audit-prev').onclick=()=>{auditPage--;draw();};$('#audit-next').onclick=()=>{auditPage++;draw();};}

 body.querySelectorAll('[data-audit-category]').forEach(b=>b.onclick=()=>{auditCategoryFilter=b.dataset.auditCategory;auditPage=1;body.querySelectorAll('[data-audit-category]').forEach(x=>x.classList.toggle('primary',x===b));draw();});
 $('#audit-query').oninput=e=>{auditQuery=e.target.value;auditPage=1;draw();};for(const key of ['from','to'])$('#audit-'+key).oninput=e=>{if(key==='from')auditFrom=e.target.value;else auditTo=e.target.value;auditPage=1;draw();};
 $('#audit-lock-new').onclick=()=>{auditUnlocked=false;auditExpanded=false;render();};$('#audit-export-filtered').onclick=()=>auditExportDialog(filteredAudit(),'目前篩選');$('#audit-export-all').onclick=()=>auditExportDialog([...(state.logs||[])].sort((a,b)=>String(b.time).localeCompare(String(a.time))),'全部紀錄');
 $('#audit-clear-new').onclick=async()=>{if(!await confirmAction('刪除全部 '+(state.logs||[]).length+' 筆操作紀錄（包括其他分類及日期，不受目前篩選限制）？無法復原。案件、庫存和照片不會刪除。'))return;state.logs=[];await saveCloud(state);if(failedCandidate){toast('尚未儲存成功');return;}auditPage=1;render();};draw();
}
function auditExportDialog(logs,scope){const snapshot=structuredClone(logs);modal('匯出'+scope,'<p>將匯出 '+snapshot.length+' 筆，包含所有符合條件的頁面。</p><label class="field">格式<select name="format"><option value="csv">Excel 可開啟的 CSV</option><option value="json">JSON 備份</option></select></label>','匯出',async fd=>{if(!await authorizeExport())throw Error('只有主管可匯出');if(fd.get('format')==='json')await downloadJSON(snapshot,'資訊庫_'+scope+'.json');else{const rows=[['時間','分類','人員','對象','操作','位置','內容'],...snapshot.map(x=>[receiptTime(x.time),auditCategories[auditCategory(x)],x.actor,auditTarget(x),x.action,auditLocation(x),x.detail])];await downloadBlob(new Blob([platingCsv(rows)],{type:'text/csv;charset=utf-8'}),'資訊庫_'+scope+'.csv');}$('#modal').close();});}
const renderBeforeAuditView=render;render=function(){renderBeforeAuditView();enhanceAuditView();};
